-- Deterministic demo: October 2025 through September 2026.
SET NAMES utf8mb4;
START TRANSACTION;
UPDATE barang b SET stok=COALESCE((SELECT SUM(jumlah) FROM barang_masuk m WHERE m.barang_id=b.id),0)-COALESCE((SELECT SUM(jumlah) FROM barang_keluar k WHERE k.barang_id=b.id),0), updated_at='2026-09-15 08:00:00';
COMMIT;
